+const mongoose = require('mongoose');
+const { User, AutomationRun } = require('./models');
+
+const LEASE_MS = Number(process.env.AUTOMATION_RUN_LEASE_MS) || 90_000;
+
+async function enqueueJobHunt(userId) {
+  const runId = new mongoose.Types.ObjectId();
+  const owner = await User.findOneAndUpdate(
+    { _id: userId, $or: [{ automationActiveRunId: null }, { automationActiveRunId: { $exists: false } }] },
+    { $set: { automationActiveRunId: runId } },
+    { new: true, projection: { _id: 1 } }
+  );
+  if (!owner) {
+    const user = await User.findById(userId).select('automationActiveRunId').lean();
+    const activeRun = user?.automationActiveRunId
+      ? await AutomationRun.findOne({ _id: user.automationActiveRunId, userId }).lean()
+      : null;
+    return { accepted: false, activeRun };
+  }
+
+  try {
+    const run = await AutomationRun.create({ _id: runId, userId, type: 'job-hunt' });
+    return { accepted: true, run };
+  } catch (error) {
+    await User.updateOne({ _id: userId, automationActiveRunId: runId }, { $set: { automationActiveRunId: null } });
+    throw error;
+  }
+}
+
+async function claimNext(workerId) {
+  const now = new Date();
+  return AutomationRun.findOneAndUpdate(
+    { status: 'queued' },
+    { $set: { status: 'running', step: 'starting', workerId, startedAt: now, leaseUntil: new Date(now.getTime() + LEASE_MS) }, $inc: { attempts: 1 } },
+    { new: true, sort: { createdAt: 1 } }
+  );
+}
+
+async function heartbeat(runId, workerId, status) {
+  const now = new Date();
+  const logs = (status.logs || []).slice(-100).map(item => ({ time: new Date(item.time), message: item.message }));
+  return AutomationRun.updateOne(
+    { _id: runId, status: 'running', workerId },
+    { $set: {
+      leaseUntil: new Date(now.getTime() + LEASE_MS),
+      step: status.step || 'running',
+      progress: Number(status.progress) || 0,
+      ...(logs.length ? { logs } : {}),
+      ...(status.error ? { error: String(status.error).slice(0, 1000) } : {}),
+    } }
+  );
+}
+
+async function finish(run, workerId, error, result) {
+  const status = error ? 'failed' : 'complete';
+  const updated = await AutomationRun.findOneAndUpdate(
+    { _id: run._id, status: 'running', workerId },
+    { $set: {
+      status,
+      step: status,
+      progress: error ? run.progress : 100,
+      error: error ? String(error.message || error).slice(0, 1000) : null,
+      result: result ? { jobsFound: result.jobsFound, highMatch: result.highMatch } : undefined,
+      finishedAt: new Date(),
+      leaseUntil: null,
+    } },
+    { new: true }
+  );
+  if (updated) await User.updateOne({ _id: run.userId, automationActiveRunId: run._id }, { $set: { automationActiveRunId: null } });
+  return updated;
+}
+
+// A crashed worker may have sent notifications before dying. Mark the run for
+// review instead of automatically replaying it and risking duplicate effects.
+async function recoverExpiredRuns() {
+  const expired = await AutomationRun.find({ status: 'running', leaseUntil: { $lte: new Date() } }).select('_id userId').lean();
+  for (const run of expired) {
+    const changed = await AutomationRun.updateOne(
+      { _id: run._id, status: 'running', leaseUntil: { $lte: new Date() } },
+      { $set: { status: 'interrupted', step: 'interrupted', error: 'Worker lease expired; review before retrying.', finishedAt: new Date(), leaseUntil: null } }
+    );
+    if (changed.modifiedCount) await User.updateOne({ _id: run.userId, automationActiveRunId: run._id }, { $set: { automationActiveRunId: null } });
+  }
+}
+
+module.exports = { LEASE_MS, enqueueJobHunt, claimNext, heartbeat, finish, recoverExpiredRuns };

