+const workerId = `${os.hostname()}-${process.pid}-${crypto.randomUUID()}`;
+const pollMs = Math.max(500, Number(process.env.AUTOMATION_QUEUE_POLL_MS) || 1500);
+let stopping = false;
+let activeRun = null;
+
+async function sleep(ms) {
+  await new Promise(resolve => setTimeout(resolve, ms));
+}
+
+async function execute(run) {
+  activeRun = run;
+  console.log(`Starting job-hunt run ${run._id} for account ${run.userId}`);
+  const pulse = setInterval(() => {
+    heartbeat(run._id, workerId, getRunStatus()).catch(error => {
+      console.error(`Could not renew lease for run ${run._id}:`, error.message);
+    });
+  }, Math.max(5000, Math.floor(Number(process.env.AUTOMATION_RUN_LEASE_MS || 90000) / 3)));
+  pulse.unref();
+
+  try {
+    const report = await runJobHunt(run.userId, false);
+    await heartbeat(run._id, workerId, getRunStatus());
+    await finish(run, workerId, null, report);
+    console.log(`Completed job-hunt run ${run._id}`);
+  } catch (error) {
+    await heartbeat(run._id, workerId, getRunStatus()).catch(() => {});
+    await finish(run, workerId, error).catch(finishError => console.error('Could not persist run failure:', finishError.message));
+    console.error(`Job-hunt run ${run._id} failed:`, error.message);
+  } finally {
+    clearInterval(pulse);
+    activeRun = null;
+  }
+}
+
+async function main() {
+  if (!process.env.MONGODB_URI) throw new Error('MONGODB_URI is required by the automation worker.');
+  await mongoose.connect(process.env.MONGODB_URI, { serverSelectionTimeoutMS: 8000 });
+  await recoverExpiredRuns();
+  console.log(`Automation queue worker ${workerId} connected.`);
+
+  while (!stopping) {
+    const run = await claimNext(workerId);
+    if (run) await execute(run);
+    else await sleep(pollMs);
+  }
+
+  if (activeRun) console.log(`Waiting for active run ${activeRun._id} to finish before shutdown.`);
+  await mongoose.disconnect();
+}
+
+for (const signal of ['SIGINT', 'SIGTERM']) {
+  process.on(signal, () => { stopping = true; });
+}
+
+main().catch(async error => {
+  console.error('Automation queue worker stopped:', error.message);
+  await mongoose.disconnect().catch(() => {});
+  process.exitCode = 1;
+});

