+
+function validName(name) { return typeof name === 'string' && /^[a-z\d_.-]{1,200}$/i.test(name) && name !== '.' && name !== '..'; }
+function localPath(kind, name, root = store.ROOT) {
+  if (!validName(name) || !['resume', 'evidence'].includes(kind)) throw new Error('Invalid private file reference.');
+  return kind === 'resume' ? path.join(root, name) : path.join(root, 'evidence', name);
